import{_ as r,o,c as a,ag as n}from"./chunks/framework.DzGOF12C.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"philosophy/China/01. 공자.md","filePath":"philosophy/China/01. 공자.md"}'),l={name:"philosophy/China/01. 공자.md"};function s(i,t,e,d,p,h){return o(),a("div",null,[...t[0]||(t[0]=[n('<h2 id="공자는-어떤-인물인가" tabindex="-1">공자는 어떤 인물인가 <a class="header-anchor" href="#공자는-어떤-인물인가" aria-label="Permalink to &quot;공자는 어떤 인물인가&quot;">​</a></h2><p><strong>시대적 배경 (춘추시대)</strong></p><ul><li>봉건적 질서가 해체되며 새로운 사회·정치·사상이 형성되던 시기</li><li>종법사회 붕괴, 엘리트 중심의 중앙집권적 관료제로 전환</li><li>과학기술 발달과 철기문명으로의 전환으로 생산량과 잉여 생산물 증가</li><li>국가 간 교류 증가와 도시 발달로 혈연 중심에서 개인·능력 중심 사회로 변화 → 사적 이익 추구 및 정복 전쟁 활성화</li></ul><p><strong>종법제도</strong>: 종(맏아들)을 중심으로 한 법제도. 대종이 소종에게 땅을 분할하고, 소종은 다시 종과 소종으로 나뉘는 혈연 중심의 귀족제. 가족적 유대감으로 묶인 관계이며, 주공이 이를 바탕으로 주나라의 봉건적 질서(주례)를 마련.</p><p><strong>문제의식</strong>: 천하무도(天下無道) — 도가 사라졌기 때문에 전쟁이 일어나 백성이 고통받는다고 진단. 따라서 도를 새로 세워야 함.</p><ul><li>해법: 종법질서의 회복, 덕치정치, 현신(현명한 신하) 등용</li><li>선비를 군자다운 존재로 만들어야 함 — 인재를 선천적 혈연 기반이 아닌 후천적 노력을 통해 인격·학문적으로 성숙된 존재로 봄 (주체적, 자율적 인간관 및 배움의 강조)</li></ul><p>시간이 지나며 촌수가 멀어져 덕·예라는 도덕적 권위만으로는 제후를 통제하기 어려워지고, 생산성 증대로 경제적 자립이 가능해지며 위계에 복종할 이유가 약해짐 — 이런 배경에서 공자는 (1) 공동체 구성원을 착한 존재로 만들고 (2) 덕치정치를 강화하고 (3) 사(士)를 군자로 만들어 질서를 자율적으로 회복하고자 함. (이와 대비되게, 객관적·강제적 규칙으로 행위를 변화시키자는 법치 사상도 함께 등장)</p><h2 id="중심-개념-인-仁-과-예-禮" tabindex="-1">중심 개념: 인(仁)과 예(禮) <a class="header-anchor" href="#중심-개념-인-仁-과-예-禮" aria-label="Permalink to &quot;중심 개념: 인(仁)과 예(禮)&quot;">​</a></h2><p><strong>인(仁)</strong>: 사람다움. &#39;사람 인(人)&#39; + &#39;두 이(二)&#39; — 두 사람 간의 바람직한 관계를 맺는 것. 인간을 관계적 존재로 보았으며, 이는 오륜에서 드러남.</p><ul><li><strong>인의 두 축 — 충(忠)과 서(恕)</strong>: 수기치인(修己治人), 즉 나를 다스려 타인을 다스림 <ul><li>충: 나에게 있어 최선을 다하는 삶</li><li>서: 내 마음을 근거로 타인을 이해하는 삶</li></ul></li></ul><p><strong>예(禮)</strong>: 인의 실현이자 사회적 규범. <strong>극기복례(克己復禮)</strong> — 나를 이기고 예로 돌아감으로써 인을 실현할 수 있음. 공자는 &#39;형식적인 예&#39;가 아니라 &#39;내면의 인&#39;을 바탕으로 한 예의 회복을 주장.</p><p><strong>정명사상(正名思想)</strong>: &quot;군군신신부부자자(君君臣臣父父子子)&quot; — 임금은 임금답고, 신하는 신하답고, 아버지는 아버지답고, 자식은 자식다워야 함. 『주례』는 각자가 사회에서 맡은 위치와 역할을 명확히 규정하여, 각자가 본분을 다할 때 사회가 안정된다고 봄. 종법적 질서를 내면화함으로써 인간관계의 근본인 효(孝)와 제(悌)가 자연스럽게 사회 전체로 확장될 수 있다고 봄.</p><h2 id="예-禮-와-법-法-의-비교" tabindex="-1">예(禮)와 법(法)의 비교 <a class="header-anchor" href="#예-禮-와-법-法-의-비교" aria-label="Permalink to &quot;예(禮)와 법(法)의 비교&quot;">​</a></h2><p><strong>공통점</strong>: 둘 다 규범이라는 점에서 비슷한 속성</p><ul><li>질서유지: 공동체 내 갈등을 방지하고 공유된 사회적 관계를 형성</li><li>행위의 기준: 무엇이 옳고 그른지 판단 근거 제공</li><li>공익성 표방: 개인의 욕망을 조절해 공동체의 안녕 도모</li></ul><p><strong>차이점</strong></p><table tabindex="0"><thead><tr><th></th><th>예(禮)</th><th>법(法)</th></tr></thead><tbody><tr><td><strong>규제 대상</strong></td><td>내면의 양심 (행위 이전의 마음가짐·태도)</td><td>외면의 행위</td></tr><tr><td><strong>동력</strong></td><td>양심의 부끄러움 (자발적 교정 유도)</td><td>이기적 공포 (처벌에 대한 두려움)</td></tr><tr><td><strong>제재 방식</strong></td><td>사회적 낙인, 관계의 단절</td><td>물리적 강제와 박탈</td></tr><tr><td><strong>유연성</strong></td><td>때·장소·상대에 따라 유연 (중용 추구)</td><td>누가 집행하든 동일한 결과 (일관성 원칙)</td></tr></tbody></table><p>예는 내면적 덕과 외면적 법 사이의 개념으로, 맹자는 예를 덕의 외연화로 보아 내면의 선한 본성을 확충하는 데 이용했고, 순자는 예를 법의 예비 단계이자 근거로 보아 외적 규범을 통해 본성을 교화하고자 함.</p><p><strong>법치 반대 논리</strong>: 백성을 형벌로 다스리면 형벌을 피하는 데에만 신경 쓰게 되어 정작 중요한 부끄러움을 모르게 됨. 따라서 덕과 예로 다스리면 스스로 바로잡게 됨.</p><h2 id="이상적-인간형과-정치" tabindex="-1">이상적 인간형과 정치 <a class="header-anchor" href="#이상적-인간형과-정치" aria-label="Permalink to &quot;이상적 인간형과 정치&quot;">​</a></h2><p><strong>군자</strong>: 배우기를 좋아하는 사람(&quot;학이시습지 불역열호&quot;), 남이 알아주지 않아도 성내지 않는 주체적 인간(&quot;인부지이불온이면 불역군자호&quot;). 공익을 우선시하고, 이익보다 옳음을, 말보다 행동을 우선시함.</p><p><strong>덕치(德治)</strong>: 공동체의 리더가 몸소 도덕적 삶을 살아감으로써 구성원들도 도덕적 삶을 살아가게 하는 것 — 솔선수범의 정치.</p>',22)])])}const _=r(l,[["render",s]]);export{u as __pageData,_ as default};
